"""Reconcile fresh evidence without converting partial/failed observations to gate passes."""
import hashlib,json,subprocess
from pathlib import Path
OUT=Path(__file__).parent;B=OUT.parent;R=OUT.parents[4]
load=lambda p:json.loads(p.read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
old=load(B/'10A1/candidate-baseline.json');pairs=[(p,sha(R/p)) for p in old['candidate_source_paths']];fp=hashlib.sha256(json.dumps(sorted(pairs),separators=(',',':')).encode()).hexdigest();assert fp==old['candidate_source_fingerprint']
manifest=load(R/'content/accepted-content-manifest.json');identity=manifest['identity']
platforms=[]
for n,name in [(1,'common-results.json'),(2,'android-results.json'),(3,'desktop-results.json'),(4,'ios-simulator-results.json'),(5,'ios-device-build-results.json'),(6,'web-results.json')]:
 p=B/f'10K{n}'/name
 if p.exists():
  x=load(p);platforms.append({'task':f'10K{n}','result':str(p.relative_to(B)),'sha256':sha(p),'status':x['status'],'candidate_source_fingerprint':fp,'scope':x.get('configured_scope',x.get('scope',x.get('limitations')))})
 else:raise AssertionError('Required executed-step result missing: '+str(p))
# Reconcile historical renderer fixture payloads to today's accepted content independently.
authored=load(R/'content/assessment-questions.json')['questions'];accepted={q['key']['question_id']:q for q in load(R/'content/accepted-assessment-questions.json')['questions']};diffs=[]
for q in authored:
 other=accepted[q['key']['question_id']];changed=[k for k in set(q)|set(other) if q.get(k)!=other.get(k)];assert set(changed)<= {'acceptance'}
 diffs.append({'question_id':q['key']['question_id'],'changed_fields':changed,'identical_renderer_payload':True})
(OUT/'renderer-fixture-reconciliation.json').write_text(json.dumps({'scope':'All1000 historical-to-accepted question payloads differ only in616 acceptance overlays; renderer proof is not scored acceptance.','all_renderer_payloads_identical':True,'questions':diffs},indent=2)+'\n')
matrix=load(B/'10A3/runtime-matrix.json');desktop=load(B/'10K1/test-reports/desktop-artwork-observations.json')['rows'];desktop_keys={(x['question_id'],x['revision'],x['dark'],float(x['font_scale'])) for x in desktop}
android_path=B/'10K2/native-evidence/heldQuestionNativeDeliveryMatrix/question-matrix-0-38.json';android=load(android_path)['rows'] if android_path.exists() else [];android_keys={(x['question_id'],x['revision'],x['dark'],float(x['font_scale'])) for x in android}
setting={x['id']:(x['theme']=='dark',float(x['font_scale'])) for x in matrix['settings']}
art=[]
for x in matrix['artwork_contexts']:
 key=(x['question_id'],x['revision'],*setting[x['setting']]);available=key in (desktop_keys if x['target']=='desktop' else android_keys if x['target']=='android' else set())
 art.append({'case_id':x['case_id'],'target':x['target'],'status':'functional_renderer_observed_required_visual_selection_failure_open' if available else 'blocked_or_not_completed_required_current_matrix','available_receipt':'10K1/test-reports/desktop-artwork-observations.json' if available and x['target']=='desktop' else str(android_path.relative_to(B)) if available else None,'closure':'open; DEF-10D-001 and remaining visual/platform requirements are not waived'})
full_flow_receipts={}
for n,name in [(2,'android-results.json'),(3,'desktop-results.json'),(4,'ios-simulator-results.json'),(6,'web-results.json')]:
 for case in load(B/f'10K{n}'/name).get('full_normal_journeys_completed',[]):full_flow_receipts[case]=f'10K{n}/{name}'
flows=[{'case_id':x['case_id'],'target':x['target'],'status':'pass_exact_normal_build_journey' if x['case_id'] in full_flow_receipts else 'open_not_full_required_normal_build_journey','full_flow_receipt':full_flow_receipts.get(x['case_id']),'available_evidence':'See target result for exact normal/proof flow fragments/settings; no fixture or subset is promoted to a complete normal-build case.','closure':'Requires exact remaining source/review/settings/assistive technology steps and defect repairs.'} for x in matrix['production_journeys']]
clauses=[dict(case_id=x['case_id'],expected=x['expected'],status='open_required_failure_or_uncompleted_matrix',platform_results=[p['result'] for p in platforms]) for x in load(B/'10A3/verification-case-index.json')['gate_clauses'] if x['gate']=='T10']
for clause in clauses:
 if clause['case_id'] in ['T10-CLAUSE-01','T10-CLAUSE-05']:
  clause['status']='pass_scoped_common_parity' if clause['case_id'].endswith('01') else 'pass_device_build_resources_with_physical_runtime_excluded'
prior=load(B/'10J3/defects.json');new_findings=load(B/'10K6/defects.json')['new_product_findings'];ledger={'task':'10K7','continues':'../10J3/defects.json','inherited_open_product_defects':prior['open_product_defects'],'open_product_defects':prior['open_product_defects']+[x['id'] for x in new_findings],'findings':prior['findings']+new_findings,'new_product_findings':new_findings,'fresh_confirmations':{'DEF-10D-001':'10K2 native checked node versus screenshot; selection visibility failure','DEF-10F-001':'10K3 invalid-input-reproduction.json; exact conditional injected identity assertion','DEF-10H-001':'10K3 reading-sign-return-observations.json; actual reader→sign→catalogue→return assertion'},'closure':'All19 product findings remain open.10K is verification; no10L repair or visual design approval is implied.','verification_blockers':['remaining exact normal/proof/assistive/source/copy/presentation matrix','source classifications/currency from10C','required selection failure and bounded repair/retest','all scope/conditional exclusions retained from prior gates']}
(OUT/'defects.json').write_text(json.dumps(ledger,indent=2)+'\n')
result={'task':'10K7','status':'executed_reconciliation_T10_and_step10_incomplete','candidate':identity,'source_runtime_fingerprint':fp,'platforms':platforms,'T10_clauses':clauses,'counts':{'artwork_cases':len(art),'functional_renderer_cases_observed':sum(x['available_receipt'] is not None for x in art),'required_artwork_cases_closed':0,'normal_production_journeys':len(flows),'normal_production_journeys_closed':len(full_flow_receipts),'inherited_product_findings':18,'new_product_findings':len(new_findings),'total_open_product_findings':len(prior['open_product_defects'])+len(new_findings)},'artwork_cases':art,'normal_production_journeys':flows,'gate_dispositions':{'T01':'Passing protected unchangedcandidate; six generation checks and fresh compiled reader/bank suite reinforce parity','T02':'Open inherited classifications/currency and remaining source-platform cases','T03':'Open fresh native selection visibility/browser semantics failures and uncompleted matrix','T04':'Open inherited30 description contexts; no content repair','T05':'Open fresh conditional identity rejection failure and full normal journey matrix','T06':'Scoped new callbacks/offline native dispatch; unobserved target/failure cases remain open','T07':'Open fresh actual sign catalogue return failure plus remaining native state contracts','T08':'Fresh full shared content/copy preserved; remaining actual visible/target/font/interaction acceptance open','T09':'Six fidelity findings and inherited classification issue remain; no new visual design approved','T10':'Open required failures and uncompleted exact matrix'},'physical_scope':'iosArm64 build/resource verification required; physical runtime/signing/install/VoiceOver/legibility excluded_unperformed under existing simulator policy','future_store_cases':'four conditional contracts remain conditional; no storage/history/import/hot replacement feature invented','next_separately_requestable_task':'10L1 — triage a bounded issue/coherent batch before repair/retest','publication':False}
(OUT/'platform-matrix.json').write_text(json.dumps(result,indent=2)+'\n')
fingerprint={'task':'10K7','candidate':identity,'manifest_file_sha256':sha(R/'content/accepted-content-manifest.json'),'candidate_source_fingerprint':fp,'expected_10A1_fingerprint':old['candidate_source_fingerprint'],'unchanged':True,'source_files':dict(sorted(pairs)),'entry_commit':load(B/'10K1/environment.json')['entry_commit'],'current_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip(),'normal_proof_builds':'Target-specific identities/resource receipts retained; proof artifacts are not release artifacts.','status':'same_candidate_not_release_accepted_by_step10'}
(OUT/'final-candidate-fingerprint.json').write_text(json.dumps(fingerprint,indent=2)+'\n');print(result['counts'])
